```python
import asyncio
import json
import os
import re
import sys
import time
from collections import deque
from pathlib import Path
from typing import Any

from firecrawl import Firecrawl
from firecrawl.v2.types import ScrapeOptions


PROJECT_ROOT = Path(__file__).resolve().parent
OUTPUT_DIRECTORY = PROJECT_ROOT / "barbie"
MAX_FILE_SIZE_BYTES = 50 * 1024 * 1024
REQUEST_TIMEOUT_MILLISECONDS = 300_000
MAX_REQUESTS_PER_MINUTE = 8
MAX_RATE_LIMIT_RETRIES = 8
request_times: deque[float] = deque()
rate_limit_lock = asyncio.Lock()


def create_firecrawl_client() -> Firecrawl:
    api_key = os.environ.get("FIRECRAWL_API_KEY")
    if not api_key:
        raise RuntimeError("A FIRECRAWL_API_KEY titok nincs beállítva.")
    return Firecrawl(api_key=api_key)


def extract_document_value(document: Any, key: str) -> Any:
    if isinstance(document, dict):
        return document.get(key)
    return getattr(document, key, None)


def normalize_json_value(value: Any) -> Any:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, list):
        return [normalize_json_value(item) for item in value]
    if isinstance(value, tuple):
        return [normalize_json_value(item) for item in value]
    if isinstance(value, dict):
        return {str(key): normalize_json_value(item) for key, item in value.items()}
    if hasattr(value, "model_dump"):
        return normalize_json_value(value.model_dump())
    if hasattr(value, "dict"):
        return normalize_json_value(value.dict())
    return str(value)


def parse_pdf_sync(client: Firecrawl, input_path: Path) -> dict[str, Any]:
    document = client.parse(
        input_path.read_bytes(),
        filename=input_path.name,
        content_type="application/pdf",
        options=ScrapeOptions(
            formats=[
                "markdown",
                {
                    "type": "json",
                    "prompt": (
                        "Translate the complete PDF content into fluent English. "
                        "Return a JSON object with exactly one field named "
                        "'translated_content', containing the full English translation. "
                        "Preserve headings, paragraphs, lists, tables, labels, numbers, "
                        "dates, names, URLs, citations, and document structure. "
                        "Do not summarize, omit, interpret, or add content."
                    ),
                    "schema": {
                        "type": "object",
                        "properties": {
                            "translated_content": {
                                "type": "string",
                                "description": "The complete English translation of the PDF."
                            }
                        },
                        "required": ["translated_content"],
                        "additionalProperties": False
                    }
                }
            ],
            timeout=REQUEST_TIMEOUT_MILLISECONDS,
            parsers=[{"type": "pdf", "mode": "auto"}],
        ),
    )

    markdown = extract_document_value(document, "markdown")
    extracted_json = extract_document_value(document, "json")

    if not isinstance(markdown, str) or not markdown.strip():
        raise RuntimeError("A Firecrawl nem adott vissza Markdown-tartalmat.")

    if extracted_json is None:
        raise RuntimeError("A Firecrawl nem adott vissza JSON-tartalmat.")

    normalized_json = normalize_json_value(extracted_json)

    if isinstance(normalized_json, str):
        try:
            normalized_json = json.loads(normalized_json)
        except json.JSONDecodeError as error:
            raise RuntimeError("A Firecrawl JSON-válasza nem érvényes JSON.") from error

    if not isinstance(normalized_json, dict):
        raise RuntimeError("A Firecrawl JSON-válasza nem JSON objektum.")

    translated_content = normalized_json.get("translated_content")
    if not isinstance(translated_content, str) or not translated_content.strip():
        raise RuntimeError("A Firecrawl JSON-válaszából hiányzik az angol fordítás.")

    return {
        "source_file": input_path.name,
        "source_path": str(input_path),
        "parsed_markdown": markdown,
        "translated_content": translated_content
    }


async def wait_for_request_slot() -> None:
    while True:
        async with rate_limit_lock:
            now = time.monotonic()
            while request_times and now - request_times[0] >= 60:
                request_times.popleft()
            if len(request_times) < MAX_REQUESTS_PER_MINUTE:
                request_times.append(now)
                return
            wait_seconds = 60 - (now - request_times[0]) + 0.25
        await asyncio.sleep(wait_seconds)


def retry_after_seconds(error: Exception) -> float:
    match = re.search(
        r"retry after\s+(\d+(?:\.\d+)?)s",
        str(error),
        flags=re.IGNORECASE,
    )
    return float(match.group(1)) + 1.0 if match else 60.0


async def parse_with_retries(client: Firecrawl, pdf_path: Path) -> dict[str, Any]:
    last_error: Exception | None = None

    for attempt in range(MAX_RATE_LIMIT_RETRIES + 1):
        await wait_for_request_slot()

        try:
            return await asyncio.to_thread(parse_pdf_sync, client, pdf_path)
        except Exception as error:
            if "rate limit exceeded" not in str(error).lower():
                raise

            last_error = error

            if attempt < MAX_RATE_LIMIT_RETRIES:
                await asyncio.sleep(retry_after_seconds(error))

    raise RuntimeError(
        f"A Firecrawl limit {MAX_RATE_LIMIT_RETRIES + 1} próbálkozás után sem oldódott fel: {last_error}"
    ) from last_error


def get_file_size(pdf_path: Path) -> int:
    return pdf_path.stat().st_size


def write_json_atomically(json_path: Path, content: dict[str, Any]) -> None:
    temporary_path = json_path.with_name(f"{json_path.name}.tmp")
    temporary_path.write_text(
        json.dumps(content, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    os.replace(temporary_path, json_path)


async def process_pdf(client: Firecrawl, pdf_path: Path) -> tuple[Path, str | None]:
    try:
        file_size = await asyncio.to_thread(get_file_size, pdf_path)

        if file_size > MAX_FILE_SIZE_BYTES:
            return pdf_path, "A fájl mérete meghaladja az 50 MB-os Firecrawl korlátot."

        if file_size == 0:
            return pdf_path, "Az üres PDF nem dolgozható fel."

        content = await parse_with_retries(client, pdf_path)
        json_path = OUTPUT_DIRECTORY / f"{pdf_path.stem}.json"
        await asyncio.to_thread(write_json_atomically, json_path, content)

        return pdf_path, None
    except Exception as error:
        return pdf_path, str(error)


async def main() -> int:
    try:
        client = create_firecrawl_client()
    except RuntimeError as error:
        print(f"HIBA: {error}", file=sys.stderr)
        return 1

    OUTPUT_DIRECTORY.mkdir(parents=True, exist_ok=True)

    pdf_paths = sorted(
        path
        for path in PROJECT_ROOT.iterdir()
        if path.is_file()
        and path.suffix.lower() == ".pdf"
        and not (OUTPUT_DIRECTORY / f"{path.stem}.json").exists()
    )

    if not pdf_paths:
        print("Nincs feldolgozandó PDF a projekt gyökérmappájában.")
        return 0

    print(
        f"{len(pdf_paths)} PDF feldolgozása indul, legfeljebb "
        f"{MAX_REQUESTS_PER_MINUTE} Firecrawl kérés/perc ütemezéssel."
    )

    results = await asyncio.gather(
        *(process_pdf(client, pdf_path) for pdf_path in pdf_paths)
    )

    failures = [(path, error) for path, error in results if error]

    for path, error in failures:
        print(f"HIBA: {path.name}: {error}", file=sys.stderr)

    print(
        f"Sikeres: {len(results) - len(failures)}. "
        f"Hibás: {len(failures)}. "
        f"Kimenet: {OUTPUT_DIRECTORY}"
    )

    return 1 if failures else 0


if __name__ == "__main__":
    raise SystemExit(asyncio.run(main()))
